changeSet.sql:
CREATE OR ALTER FUNCTION [dbo].[GetAssetLevelById] ( @Id bigint ) RETURNS TABLE AS RETURN ( with c as ( select T.ID as AssetID, T.Object as AssetObject, T.ObjectID as AssetObjectID, T.ID, T.Object, T.ObjectID, 1 as Level from Asset T cross apply dbo.GetAssetDisplayValueById(T.ID) D left join PredicateIntersect I on I.Object = T.Object and I.ObjectID = T.ObjectID and I.PredicateType in (3, 4) where T.ID = @Id union all select c.AssetID, c.AssetObject, c.AssetObjectID, T.ID, T.Object, T.ObjectID, c.Level + 1 as Level from Asset T cross apply dbo.GetAssetDisplayValueById(T.ID) D inner join PredicateIntersect I on I.Subject = T.Object and I.SubjectID = T.ObjectID and I.PredicateType in (3, 4) inner join c on I.Object = c.Object and I.ObjectID = c.ObjectID
)
select top 1 AssetID as ID, AssetObject as Object, AssetObjectID as ObjectID, Level from c order by Level desc )
